const RELEASE='v3.1.0'; // Internal only; not displayed publicly.
// Never leave visitors with an unhelpful black page after a React rendering failure.
export class CrashBoundary extends React.Component {
 constructor(props){super(props);this.state={error:null};}
 static getDerivedStateFromError(error){return {error};}
 componentDidCatch(error,info){console.error('NEXBOTS page error',error,info.componentStack);}
 render(){
  if(!this.state.error)return this.props.children;
  return <section className="page-content"><div className="auth-panel recovery-panel" role="alert">
   <AlertCircle size={43}/><h2>تعذّر عرض هذه الصفحة</h2>
   <p>حدث خطأ غير متوقع أثناء عرض المحتوى. يمكنك إعادة المحاولة أو العودة للرئيسية. قد تحتاج إلى اختيار الملفات مجدداً إذا لم يكتمل رفعها.</p>
   <div className="recovery-actions"><button type="button" className="btn btn-primary" onClick={()=>this.setState({error:null})}><RefreshCw size={17}/>إعادة المحاولة</button><a className="btn btn-outline" href="/">الصفحة الرئيسية <Home size={17}/></a></div>
  </div></section>;
 }
}
function SafeRouteView(){const location=useLocation();return <CrashBoundary key={location.pathname+location.search}><RouteView/></CrashBoundary>;}
async function shareProfileLink(uid,displayName,toast){
 const link=`${window.location.origin}/u/${encodeURIComponent(uid)}`;
 if(navigator.share){try{await navigator.share({title:`${displayName} | NEXBOTS`,url:link});return;}catch(e){if(e?.name==='AbortError')return;}}
 try{if(navigator.clipboard?.writeText)await navigator.clipboard.writeText(link);
 else{const el=document.createElement('textarea');el.value=link;el.style.position='fixed';el.style.opacity='0';document.body.appendChild(el);el.select();if(!document.execCommand('copy'))throw new Error('copy failed');el.remove();}
 toast('تم نسخ رابط البروفايل — شاركه مع أصدقائك');
 }catch{window.prompt('انسخ رابط البروفايل:',link);}
}
function GoogleMark({size=19}){return <img className="google-mark" src={brandIcons.google} width={size} height={size} alt="" aria-hidden="true"/>;}

function useFetch(fn,deps=[]){const [data,setData]=useState(null),[loading,setLoading]=useState(true),[error,setError]=useState('');const reload=useCallback(()=>{let active=true;setLoading(true);Promise.resolve().then(fn).then(d=>{if(active){setData(d);setError('');}}).catch(e=>{if(active)setError(e.message);}).finally(()=>{if(active)setLoading(false);});return()=>{active=false;};},deps);useEffect(()=>reload(),[reload]);return{data,loading,error,reload,setData};}
function IconLogo({size=48}){const{site}=useApp();return <img className="brand-image" src={site.logo?'/api/media/brand/logo':logo} alt="شعار NEXBOTS" width={size} height={size}/>;}
function App(){
 const[firebaseUser,setFirebaseUser]=useState(undefined),[me,setMe]=useState(null),[site,setSite]=useState(defaultSite),[plans,setPlans]=useState(defaultPlans),[serviceError,setServiceError]=useState(null),[busy,setBusy]=useState(false),[authError,setAuthError]=useState(''),[notice,setNotice]=useState(null),[mobile,setMobile]=useState(false),[offline,setOffline]=useState(typeof navigator!=='undefined'&&!navigator.onLine);
 const toast=(message,type='success')=>{setNotice({message,type,at:Date.now()});};
 useEffect(()=>{const update=()=>setOffline(!navigator.onLine);window.addEventListener('online',update);window.addEventListener('offline',update);return()=>{window.removeEventListener('online',update);window.removeEventListener('offline',update);};},[]);
 const refreshMe=useCallback(async()=>{if(!auth.currentUser){setMe(null);setAuthError('');return;}try{const result=await api('me');if(!result?.user||!result.user.uid)throw new Error('بيانات الحساب غير مكتملة، حاول إعادة المحاولة');setMe({...result.user,displayName:result.user.displayName||'عضو NEXBOTS',activePlan:result.activePlan||'free',email:result.private?.email||''});setAuthError('');}catch(e){setMe(null);setAuthError(!navigator.onLine?'لا يتوفر اتصال بالإنترنت حالياً. يرجى تشغيل الإنترنت والمحاولة من جديد.':(e?.message||'تعذّر تحميل حسابك'));toast(!navigator.onLine?'لا يتوفر اتصال بالإنترنت حالياً. يرجى تشغيل الإنترنت والمحاولة من جديد.':(e?.message||'تعذّر تحميل حسابك'),'error');}},[]);
 const refreshConfig=useCallback(async()=>{
   try{
     const data=await api('public');
     if(data?.settings&&typeof data.settings==='object')setSite({...defaultSite,...data.settings});
     if(data?.plans&&typeof data.plans==='object')setPlans({...defaultPlans,...data.plans});
     cachePublicSettings(data);setServiceError(null);
   }catch(e){
     const saved=readPublicSettings();
     if(saved){setSite({...defaultSite,...saved.settings});setPlans({...defaultPlans,...saved.plans});
       // Previously seen public data is available; only the offline banner is needed.
       if(!navigator.onLine){setServiceError(null);return;}
     }
     setServiceError(publicStatus(e,navigator.onLine));
     console.warn('NEXBOTS public config unavailable:',e?.message);
   }
 },[]);
 const previousOffline=useRef(offline);
 useEffect(()=>{const wasOffline=previousOffline.current;previousOffline.current=offline;
   if(wasOffline&&!offline)refreshConfig();},[offline,refreshConfig]);
 useEffect(()=>{refreshConfig();const unsub=onAuthStateChanged(auth,user=>setFirebaseUser(user),error=>{console.error('Firebase Auth:',error);setFirebaseUser(null);setAuthError('تعذّر التحقق من تسجيل الدخول');toast('تعذّر الاتصال بتسجيل الدخول، جرّب تحديث الصفحة','error');});return unsub;},[refreshConfig]);
 useEffect(()=>{if(firebaseUser!==undefined)refreshMe();},[firebaseUser,refreshMe]);
 useEffect(()=>{if(firebaseUser!==undefined)return;const timer=setTimeout(()=>{setFirebaseUser(null);setAuthError('تعذّر استكمال الاتصال بـGoogle، جرّب تسجيل الدخول من جديد');},16000);return()=>clearTimeout(timer);},[firebaseUser]);
 useEffect(()=>{if(!notice)return;const t=setTimeout(()=>setNotice(null),5000);return()=>clearTimeout(t);},[notice]);
 useEffect(()=>{document.title=`${site.siteName} | ${site.tagline}`;const el=document.querySelector('link[rel="icon"]');if(el)el.href=site.logo?'/api/media/brand/logo':logo;},[site]);
 const preventOfflineAction=(event)=>{
   if(!offline)return;
   const el=event.target?.closest?.('button,[role="button"],input[type="submit"],a[href]');
   if(!el)return;
   // Local navigation is allowed, but it never unlocks private data or writes.
   if(el.matches('a[href]') && (el.getAttribute('href')||'').startsWith('/'))return;
   if(el.hasAttribute('data-offline-retry') || el.getAttribute('aria-label')==='فتح القائمة')return;
   event.preventDefault();event.stopPropagation();
   toast('تعذّر تنفيذ الإجراء دون اتصال بالإنترنت. أعد المحاولة بعد عودة الشبكة.','error');
 };
 const preventOfflineSubmit=(event)=>{
   if(!offline)return;
   event.preventDefault();event.stopPropagation();
   toast('تعذّر الإرسال دون اتصال بالإنترنت. حاول مجددًا عند عودة الاتصال.','error');
 };
 const signIn=async()=>{try{setBusy(true);await login();await refreshMe();}catch(e){toast('فشل تسجيل الدخول: '+e.message,'error');}finally{setBusy(false);}};
 const signOut=async()=>{await logout();setMe(null);toast('تم تسجيل الخروج');};
 return <C.Provider value={{firebaseUser,me,site,plans,refreshMe,refreshConfig,toast,signIn,signOut,busy,authError,serviceError}}>
  <div className="app-shell" onClickCapture={preventOfflineAction} onSubmitCapture={preventOfflineSubmit}>{offline&&<div className="offline-readonly-banner" role="status">وضع دون اتصال — تصفح الأقسام، وأعد المحاولة عند عودة الإنترنت. الإرسال والرفع والدفع متوقف.</div>}<Header onMenu={()=>setMobile(v=>!v)}/><div className="layout"><Sidebar mobile={mobile} close={()=>setMobile(false)}/><main className="main-area" id="main-content">{serviceError&&<div className="service-warning" role="alert"><AlertCircle size={19}/><div><strong>{serviceError.title}</strong><small>{serviceError.message}</small></div><button type="button" onClick={refreshConfig} data-offline-retry="true" className="btn btn-outline btn-sm"><RefreshCw size={15}/> إعادة المحاولة</button></div>}{authError?.includes('تم حظر حسابك')?<div className="auth-panel banned-view" role="alert"><Shield size={45}/><h2>تم حظر حسابك من المنصة</h2><p>يرجى التواصل مع فريق الدعم لمراجعة الحظر.</p><a className="btn btn-primary" href="mailto:lllbx5ll@gmail.com">مراسلة فريق الدعم</a><button className="btn btn-outline" onClick={signOut}>تسجيل الخروج</button></div>:<SafeRouteView/>}</main></div><Footer/></div>
  {notice&&<div className={'toast '+(notice.type==='error'?'toast-error':'')} role="status">{notice.type==='error'?<AlertCircle size={18}/>:<CheckCircle2 size={18}/>}<span>{notice.message}</span><button aria-label="إغلاق" onClick={()=>setNotice(null)}><X size={16}/></button></div>}
 </C.Provider>;
}
function Header({onMenu}){const{site,me,signIn,signOut,busy}=useApp();return <header className="topbar"><div className="topbar-in"><button className="icon-button hamburger" aria-label="فتح القائمة" onClick={onMenu}><Menu size={24}/></button><Link to="/" className="brand"><IconLogo size={49}/><span className="brand-text"><strong>{site.siteName}</strong><small>THE NEXT GENERATION </small></span></Link><div className="top-search" onClick={()=>document.getElementById('global-search')?.focus()}><Search size={18}/><span>ابحث عن بوتات، أوامر، سكربتات...</span><span className="search-shortcut">⌘ K</span></div><div className="top-actions"><Link className="header-action" to="/explore"><Compass size={19}/></Link><Link className="header-action" to="/plans"><Crown size={19}/></Link>{me?<div className="account-menu"><Link to="/account" className="user-chip"><Avatar user={me} size={34}/><span>{String(me.displayName||'عضو').split(' ')[0]}</span></Link><button className="header-action" aria-label="تسجيل الخروج" title="تسجيل الخروج" onClick={signOut}><LogOut size={18}/></button></div>:<button className="btn btn-primary btn-sm" onClick={signIn} disabled={busy}><GoogleMark size={19}/>دخول Google</button>}</div></div></header>}
const menu=[['/','الرئيسية',Home],['/explore','استكشاف المشاريع',Compass],['/chat','شات المجتمع',MessageCircle],['/private','الخاص والستوريات',MessageCircle],['/upload','رفع مشروع',UploadCloud],['/plans','العضويات',Crown],['/account','ملفي الشخصي',UserRound],['/verification','طلب التوثيق',BadgeCheck],['/support','الدعم والتواصل',Mail]];
function Sidebar({mobile,close}){const{me,site}=useApp();return <><div className={'sidebar-backdrop '+(mobile?'show':'')} onClick={close}/><aside className={'sidebar '+(mobile?'mobile-open':'')}><div className="side-caption">القائمة الرئيسية</div><nav className="side-nav">{menu.map(([href,name,I])=><NavLink key={href} to={href} onClick={()=>{close();}} end={href==='/'} className={({isActive})=>'side-link '+(isActive?'selected':'')}><I size={19}/><span>{name}</span>{href==='/plans'&&<span className="side-glow">★</span>}</NavLink>)}</nav>{me&&(me.role==='owner'||me.role==='developer')&&<><div className="side-caption gap-top">الإدارة</div><nav className="side-nav"><NavLink to="/admin" onClick={close} className={({isActive})=>'side-link '+(isActive?'selected':'')}><LayoutDashboard size={19}/>لوحة التحكم</NavLink></nav></>}<div className="sidebar-spacer"/><div className="side-premium"><div className="premium-icon"><Crown size={22}/></div><strong>ارفع مستوى تجربتك</strong><p>استمتع بالمميزات الحصرية وشارك مشاريعك مع مجتمع المطورين.</p><Link to="/plans" onClick={close} className="btn btn-primary btn-sm full">اكتشف الباقات <ArrowLeft size={16}/></Link></div><div className="side-bottom"><div className="online-dot"/>NEXBOTS SYSTEM</div></aside></>}
function Footer(){const{site}=useApp();return <footer className="footer"><span>© {new Date().getFullYear()} {site.siteName} • صُنع بشغف للمطورين </span><div><Link to="/explore">المشاريع</Link><Link to="/plans">العضويات</Link><Link to="/support">الدعم</Link></div></footer>}
function RouteView(){const loc=useLocation();useEffect(()=>{try{window.scrollTo({top:0,behavior:'auto'});}catch{}},[loc.pathname]);const path=loc.pathname.replace(/\/+$/, '')||'/';
 if(path==='/')return <HomePage/>;
 if(path==='/explore')return <ExplorePage/>;
 if(path.startsWith('/project/'))return <ProjectPage/>;
 if(path==='/upload')return <RequireAuth><UploadPage/></RequireAuth>;
 if(path==='/chat')return <RequireAuth><ChatPage/></RequireAuth>;
 if(path==='/private'||path.startsWith('/private/t/'))return <RequireAuth><CommunityEntry/></RequireAuth>;
 if(path==='/plans')return <PlansPage/>;
 if(path==='/support')return <SupportPage/>;
 if(path==='/verification')return <VerificationPage/>;
 if(path==='/account')return <RequireAuth><AccountPage/></RequireAuth>;
 if(path.startsWith('/u/'))return <PublicProfile/>;
 if(path==='/admin')return <RequireAuth><AdminPage/></RequireAuth>;
 return <div className="empty wide"><Bot size={55}/><h2>الصفحة غير موجودة</h2><Link to="/" className="btn btn-primary">العودة للرئيسية</Link></div>;
}
function CommunityEntry(){const app=useApp();return <CommunityHub app={app}/>;}
function RequireAuth({children}){const{firebaseUser,me,signIn,authError,refreshMe}=useApp();if(firebaseUser===undefined)return <Loading/>;if(!firebaseUser)return <div className="auth-panel"><div className="auth-halo"><LockKeyhole size={44}/></div><h2>مجتمعنا يبدأ بخطوة</h2><p>سجّل الدخول بحساب Google لتشارك في الشات، تحمّل المشاريع، وتدير حسابك.</p><button className="btn btn-primary" onClick={signIn}><GoogleMark size={20}/>متابعة باستخدام Google</button></div>;if(!me)return authError?<div className="auth-panel"><AlertCircle size={42}/><h2>تعذر تحميل الحساب</h2><p>{authError}</p><button className="btn btn-primary" onClick={refreshMe}><RefreshCw size={17}/>إعادة المحاولة</button></div>:<Loading/>;return children;}
