function Avatar({user,size=42}){const [failed,setFailed]=useState(false);const avatarKey=user?.avatar||'';useEffect(()=>setFailed(false),[avatarKey]);let url=avatarKey;if(url.startsWith('profiles/')||url.startsWith('/api/'))url=`/api/media/profile/${user?.uid||user?.id}/avatar?v=${encodeURIComponent(avatarKey)}`;return url&&!failed?<img className="avatar" alt="الصورة الشخصية" src={url} onError={()=>setFailed(true)} style={{width:size,height:size}}/>:<span className="avatar avatar-letter" style={{width:size,height:size,fontSize:size*.39}}>{user?.displayName?.[0]||'N'}</span>}
